  const toolChoiceRecord = asPlainRecord(toolChoice);
  if (
    toolChoiceRecord?.type === "function" &&
    typeof toolChoiceRecord.name === "string" &&
    toolChoiceRecord.name.trim().length > 0
  ) {
    return {
      type: "function",
      function: {
