    null,
    2,
  );
  return [
    {
      role: "system",
      content: buildControllerSystemPrompt({
        roleDefinitions: input.roleDefinitions,
        taskDefinitions: input.taskDefinitions,
        candidateEndpointIds: input.candidateEndpointIds,
      }),
