  value: string | null | undefined,
): RuntimeRoutingMode | null {
  const normalized = value?.trim().toLowerCase() ?? "";
  switch (normalized) {
    case "baseline":
    case "basic":
    case "balanced":
    case "latency":
    case "quality":
    case "cost":
    case "low-latency":
    case "high-quality":
    case "low-cost":
    case "latency-first":
      return "baseline";
    case "controller":
    case "intelligent":
      return "controller";
    case "difficulty":
      return "difficulty";
    case "hybrid":
      return "hybrid";
    default:
