  }
  return {
    auth_mode: "chatgpt",
    last_refresh: new Date().toISOString(),
    tokens: {
      access_token: accessToken,
      refresh_token: refreshToken,
      account_id: readOpenAICodexAccountIdFromAccessToken(accessToken),
    },
  };
}

