          ? await options.readHealthStatus()
          : {
              status: "healthy",
              executionMode: "decision_only",
              vendors: {},
              inactiveVendors: [],
            },
      );
      return;
    }

    if (request.method === "GET" && url.pathname === "/health") {
      writeText(response, 200, "OK");
      return;
    }

    if (request.method === "POST" && url.pathname === "/api/role-model/runtime/shutdown") {
      if (!options.shutdown) {
