    if (!response.ok) {
      throw new Error(`GET ${apiBase}/models returned HTTP ${response.status}.`);
    }
    const payload = (await response.json()) as { data?: Array<{ id?: unknown }> };
    if (!Array.isArray(payload.data)) {
