    const account = currentAccounts.find((entry) => entry.providerAccountId === providerAccountId);
    if (!account) {
      throw new Error(`Provider account ${providerAccountId} was not found.`);
    }
    if (account.status !== "active" || account.healthStatus !== "healthy") {
