function createResponsesStreamChunks(
  result: BridgeResponsesExecutionResult,
): ReadonlyArray<Record<string, unknown>> {
  const messageId = `msg_${result.responseId}`;
  const createdAt = Math.floor(Date.now() / 1000);
  const chunks: Record<string, unknown>[] = [
    {
      type: "response.created",
      response: {
        id: result.responseId,
        created_at: createdAt,
        model: result.model,
      },
    },
    {
      type: "response.output_item.added",
      output_index: 0,
      item: {
        type: "message",
        id: messageId,
      },
    },
  ];

  if (result.outputText.length > 0) {
    chunks.push({
      type: "response.output_text.delta",
      item_id: messageId,
      output_index: 0,
      delta: result.outputText,
    });
  }

  for (const [index, toolCall] of (result.toolCalls ?? []).entries()) {
    const outputIndex = index + 1;
    chunks.push({
      type: "response.output_item.added",
      output_index: outputIndex,
      item: {
        type: "function_call",
        id: toolCall.id,
        call_id: toolCall.id,
        name: toolCall.function.name,
        arguments: "",
      },
    });
    chunks.push({
      type: "response.function_call_arguments.delta",
      item_id: toolCall.id,
      output_index: outputIndex,
      delta: toolCall.function.arguments,
    });
    chunks.push({
      type: "response.output_item.done",
      output_index: outputIndex,
      item: {
        type: "function_call",
        id: toolCall.id,
        call_id: toolCall.id,
        name: toolCall.function.name,
        arguments: toolCall.function.arguments,
        status: "completed",
      },
    });
  }

  chunks.push({
    type: result.finishReason === "stop" ? "response.completed" : "response.incomplete",
    response: {
      id: result.responseId,
      usage: {
        input_tokens: result.usage.inputTokens,
        output_tokens: result.usage.outputTokens,
      },
      ...(result.finishReason === "stop"
        ? {}
        : {
            incomplete_details: {
              reason: result.finishReason,
            },
          }),
    },
  });

  return chunks;
}

