function parsePatchTargetPath(diff: string): string | null {
  const lines = diff.split(/\r?\n/);
  for (const line of lines) {
    if (line.startsWith("+++ ")) {
      return line.slice(4).replace(/^b\//, "").trim();
    }
  }
  for (const line of lines) {
    if (line.startsWith("--- ")) {
